import{_ as e,o as a,c as o,a3 as s}from"./chunks/framework.B9qR_F1m.js";const u=JSON.parse('{"title":"Set up ripeat with your AI assistant","description":"","frontmatter":{},"headers":[],"relativePath":"ai-setup.md","filePath":"ai-setup.md"}'),i={name:"ai-setup.md"};function n(r,t,p,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="set-up-ripeat-with-your-ai-assistant" tabindex="-1">Set up ripeat with your AI assistant <a class="header-anchor" href="#set-up-ripeat-with-your-ai-assistant" aria-label="Permalink to &quot;Set up ripeat with your AI assistant&quot;">​</a></h1><p>Copy the prompt below and paste it into your AI assistant (Claude Code, Codex, or another that can run commands on your computer). The assistant reads the setup instructions on this page, installs ripeat, and connects itself to it. It asks you before making changes.</p><h2 id="the-prompt" tabindex="-1">The prompt <a class="header-anchor" href="#the-prompt" aria-label="Permalink to &quot;The prompt&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read https://ripeat.github.io/ai-setup.md and follow the agent setup instructions to install ripeat and connect it to this assistant. Ask me before making changes.</span></span></code></pre></div><h2 id="agent-setup-instructions" tabindex="-1">Agent setup instructions <a class="header-anchor" href="#agent-setup-instructions" aria-label="Permalink to &quot;Agent setup instructions&quot;">​</a></h2><p>ripeat sets up a machine from a list and can undo its changes. Follow these steps when the person asks you to install ripeat and connect it to their assistant:</p><ol><li>Before each command, say what it does and wait for the person to agree. Never add <code>--yes</code>, <code>--accept-risk</code> or <code>--allow-admin</code>, and never pipe a download into a shell.</li><li>Check whether ripeat is already installed. If it is missing, use Homebrew on macOS or Linux (<code>brew install ripeat/tap/ripeat</code>), or Scoop on Windows (<code>scoop install git</code>, <code>scoop bucket add ripeat https://github.com/ripeat/scoop-bucket</code>, then <code>scoop install ripeat</code>). If the appropriate package manager is missing, stop and tell the person; do not install it for them.</li><li>Check the installation with <code>ripeat version</code>.</li><li>Connect the assistant using <code>ripeat mcp setup --client claude-code</code>, <code>claude-desktop</code>, or <code>codex</code>, as appropriate. Show what will change and let the setup command ask. Do not use <code>--allow-run</code>. If the assistant is not supported, explain that and stop rather than guessing its configuration.</li><li>Stop and tell the person to restart the assistant or app to pick up the connection. Do not install their other tools unless they make a separate request.</li></ol><h2 id="what-it-can-and-cannot-do" tabindex="-1">What it can and cannot do <a class="header-anchor" href="#what-it-can-and-cannot-do" aria-label="Permalink to &quot;What it can and cannot do&quot;">​</a></h2><ul><li><strong>It can</strong> install ripeat through Homebrew or Scoop, check the version, and register ripeat&#39;s MCP server with your assistant using <a href="./mcp#connecting"><code>ripeat mcp setup</code></a>, which shows the change, keeps a backup of any file it edits and asks first.</li><li><strong>It cannot</strong> install your tools (the prompt tells the assistant not to, and without <code>--allow-run</code> ripeat&#39;s server offers no install tool at all), accept a risk for you, or add <code>--yes</code>.</li><li>The prompt lives on this site over HTTPS, so what you paste is what is published here. An assistant is an instruction follower, not a lock: the real protections are ripeat&#39;s own confirmations and the <a href="./admin-policy">administrator policy</a>, not the wording of the prompt.</li></ul><p>An assistant that only has a shell can also use <a href="./agent-skill">the skill</a>.</p><p>After the restart, ask the assistant something like &quot;Set up git, node and ripgrep on this machine.&quot; It looks each one up, builds the plan and its risk rating, and gives you the <code>ripeat install</code> command to read and run yourself. To let it run the install after you confirm each run in its own app, see <a href="./mcp#letting-the-assistant-install-ripeat-mcp---allow-run-off-by-default">ripeat as an MCP server</a>.</p>',11)])])}const m=e(i,[["render",n]]);export{u as __pageData,m as default};
